#include "zkbd.h"

// -- layout lookup --

static char lower_ascii(char c) {
	return (c >= 'A' && c <= 'Z') ? (char)(c + 32) : c;
}

int z_kbd_layout_find(const char *name) {

	if (!name) return -1;

	for (int i = 0; i < z_kbd_layout_count && i < Z_KBD_LAYOUT_MAX; i++) {
		const char *a = z_kbd_layouts[i].name, *b = name;
		while (*a && *b && lower_ascii(*a) == lower_ascii(*b)) { a++; b++; }
		if (!*a && !*b) return i;
	}

	return -1;

}

const z_kbd_layout_t *z_kbd_layout_info(int id) {
	if (id < 0 || id >= z_kbd_layout_count) id = 0;
	return &z_kbd_layouts[id];
}

static const z_kbd_key_t *find_key(const z_kbd_layout_t *l, uint8_t usage) {

	// ~50 entries, sorted: a binary search is four or five probes.
	int lo = 0, hi = (int)l->nkeys - 1;
	while (lo <= hi) {
		int mid = (lo + hi) / 2;
		if (l->keys[mid].usage == usage) return &l->keys[mid];
		if (l->keys[mid].usage < usage) lo = mid + 1;
		else hi = mid - 1;
	}
	return NULL;

}

// -- case --
//
// Caps Lock acts on a key whose two levels are a lower/upper case pair.
// That has to be decided from the characters, not from the key's
// position: a-umlaut is a letter on German and a punctuation position
// on US. These are the pairs the layouts can produce.

static bool case_pair(uint32_t lo, uint32_t up) {

	if (lo >= 'a' && lo <= 'z') return up == lo - 32;
	// Latin-1: 0xE0-0xFE lower, 0xC0-0xDE upper, except the division
	// and multiplication signs at 0xF7/0xD7.
	if (lo >= 0xE0 && lo <= 0xFE && lo != 0xF7) return up == lo - 32;
	// Latin Extended-A: mostly pairs at (even upper, odd lower).
	if (lo >= 0x0100 && lo <= 0x017F) return up + 1 == lo || up == lo - 1;
	// Greek and Cyrillic, for the day a layout has them.
	if (lo >= 0x03B1 && lo <= 0x03C9) return up == lo - 32;
	if (lo >= 0x0430 && lo <= 0x044F) return up == lo - 32;
	return false;

}

// -- keys that are the same on every layout --

static uint32_t fixed_key(uint8_t usage, char kp_decimal) {

	switch (usage) {

		case 0x28: return 0x0d;   // Enter -> CR
		case 0x29: return 0x1b;   // Escape
		case 0x2A: return 0x7f;   // Backspace -- DEL, matching zeitlos.c's
		                          // readline(), which accepts either CH_BS
		                          // or CH_DEL
		case 0x2B: return '\t';   // Tab
		case 0x2C: return ' ';    // Space

		case 0x3A: return Z_KEY_F1;
		case 0x3B: return Z_KEY_F2;
		case 0x3C: return Z_KEY_F3;
		case 0x3D: return Z_KEY_F4;
		case 0x3E: return Z_KEY_F5;
		case 0x3F: return Z_KEY_F6;
		case 0x40: return Z_KEY_F7;
		case 0x41: return Z_KEY_F8;
		case 0x42: return Z_KEY_F9;
		case 0x43: return Z_KEY_F10;
		case 0x44: return Z_KEY_F11;
		case 0x45: return Z_KEY_F12;

		case 0x49: return Z_KEY_INSERT;
		case 0x4A: return Z_KEY_HOME;
		case 0x4B: return Z_KEY_PAGEUP;
		case 0x4C: return Z_KEY_DELETE;
		case 0x4D: return Z_KEY_END;
		case 0x4E: return Z_KEY_PAGEDOWN;
		case 0x4F: return Z_KEY_RIGHT;
		case 0x50: return Z_KEY_LEFT;
		case 0x51: return Z_KEY_DOWN;
		case 0x52: return Z_KEY_UP;

		// The keypad types digits and operators whatever the Num Lock
		// state (zkbd.h, "lock keys", on why Num Lock starts off). Its
		// decimal key follows the layout: a comma on German.
		case 0x54: return '/';
		case 0x55: return '*';
		case 0x56: return '-';
		case 0x57: return '+';
		case 0x58: return 0x0d;   // keypad Enter
		case 0x59: case 0x5A: case 0x5B: case 0x5C: case 0x5D:
		case 0x5E: case 0x5F: case 0x60: case 0x61:
			return (uint32_t)('1' + (usage - 0x59));
		case 0x62: return '0';
		case 0x63: return (uint32_t)(unsigned char)kp_decimal;
		case 0x67: return '=';    // keypad = (Mac keyboards)

		default: return Z_KEY_NONE;

	}

}

// -- translation --

uint32_t z_kbd_translate(int layout, uint8_t usage, uint8_t modifiers,
	uint8_t locks, uint8_t *mods_out) {

	const z_kbd_layout_t *l = z_kbd_layout_info(layout);

	if (mods_out) *mods_out = modifiers;

	// Bare modifiers (and the pseudo-usages sw/os/hid.c synthesises for
	// them) have no keysym.
	if (usage >= 0xE0) return Z_KEY_NONE;

	const z_kbd_key_t *k = find_key(l, usage);
	if (!k) return fixed_key(usage, l->kp_decimal ? l->kp_decimal : '.');

	bool shift = (modifiers & Z_KBD_MOD_SHIFT) != 0;
	bool ctrl  = (modifiers & Z_KBD_MOD_CTRL) != 0;
	bool altgr = l->altgr && (modifiers & Z_KBD_MOD_RALT) != 0;
	bool caps  = (locks & Z_KBD_LOCK_CAPS) != 0;

	// A key with nothing on its AltGr levels behaves as if AltGr were
	// not held: plain or shifted character, right Alt left in place.
	if (altgr && !k->sym[2] && !k->sym[3]) altgr = false;

	int base = altgr ? 2 : 0;
	bool up = shift;
	if (caps && case_pair(k->sym[base], k->sym[base + 1])) up = !up;

	uint32_t v = k->sym[base + (up ? 1 : 0)];
	// A level xkb leaves empty on an otherwise-used key types nothing.
	if (!v) return Z_KEY_NONE;

	if (altgr && mods_out) *mods_out = (uint8_t)(modifiers & ~Z_KBD_MOD_RALT);

	// Ctrl + a key whose plain character is a Latin letter: the control
	// code for that letter, whatever Shift, Caps Lock or AltGr say --
	// the same rule as before layouts, applied to the layout's letter.
	uint32_t plain = k->sym[0];
	if (ctrl && !altgr) {
		if (plain >= 'a' && plain <= 'z') return plain - 'a' + 1;
		if (plain >= 'A' && plain <= 'Z') return plain - 'A' + 1;
	}

	if (v >= Z_KBD_DEAD_BASE && v < Z_KBD_DEAD_BASE + 0x100)
		return Z_KEY_DEAD(v - Z_KBD_DEAD_BASE);

	return v;

}

uint32_t z_kbd_event_to_keysym(int32_t ev, uint8_t *mods_out) {
	return z_kbd_translate((int)Z_KBD_EV_LAYOUT(ev), Z_KBD_EV_USAGE(ev),
		Z_KBD_EV_MODS(ev), (uint8_t)Z_KBD_EV_LOCKS(ev), mods_out);
}

uint32_t z_kbd_usage_to_keysym(uint8_t usage, uint8_t modifiers) {
	return z_kbd_translate(0, usage, modifiers, 0, NULL);
}

// -- dead keys --

uint32_t z_kbd_compose(uint32_t dead, uint32_t cp) {

	if (!Z_KEY_IS_DEAD(dead) || cp > 0xFFFF) return 0;

	uint16_t d = (uint16_t)(Z_KBD_DEAD_BASE + (dead - Z_KEY_DEAD_BASE));
	uint16_t b = (uint16_t)cp;

	int lo = 0, hi = z_kbd_compose_count - 1;
	while (lo <= hi) {
		int mid = (lo + hi) / 2;
		const z_kbd_compose_t *e = &z_kbd_compose_table[mid];
		if (e->dead == d && e->base == b) return e->result;
		if (e->dead < d || (e->dead == d && e->base < b)) lo = mid + 1;
		else hi = mid - 1;
	}
	return 0;

}

uint32_t z_kbd_dead_spacing_of(uint32_t dead) {
	if (!Z_KEY_IS_DEAD(dead)) return 0;
	uint32_t n = dead - Z_KEY_DEAD_BASE;
	if (n >= (uint32_t)z_kbd_dead_count) return 0;
	return z_kbd_dead_spacing[n];
}

