#define ROMAJI_N ((int)(sizeof(romaji) / sizeof(romaji[0])))

static const z_kbd_romaji_t *romaji_exact(const char *s) {
	int lo = 0, hi = ROMAJI_N - 1;
	while (lo <= hi) {
		int mid = (lo + hi) / 2;
		int c = strcmp(romaji[mid].romaji, s);
		if (!c) return &romaji[mid];
		if (c < 0) lo = mid + 1;
		else hi = mid - 1;
	}
	return NULL;
}

// True if some entry is LONGER than `s` and starts with it -- the
// letters could still grow into it, so they wait.
static bool romaji_prefix(const char *s, int n) {
	for (int i = 0; i < ROMAJI_N; i++)
		if (!strncmp(romaji[i].romaji, s, (size_t)n) && romaji[i].romaji[n])
			return true;
	return false;
}

static uint32_t kana_out(const z_kbd_ime_t *ime, uint16_t cp) {
	// Katakana is hiragana shifted by 0x60, U+3041-U+3096 -> U+30A1-U+30F6.
	if (ime->mode == Z_KBD_IME_KATAKANA && cp >= 0x3041 && cp <= 0x3096)
		return (uint32_t)cp + 0x60;
	return cp;
}

static int emit_entry(const z_kbd_ime_t *ime, const z_kbd_romaji_t *e, uint32_t *out) {
	int k = 0;
	out[k++] = kana_out(ime, e->kana[0]);
	if (e->kana[1]) out[k++] = kana_out(ime, e->kana[1]);
	return k;
}

static void pend_drop(z_kbd_ime_t *ime, int k) {
	for (int i = k; i <= ime->n; i++) ime->pend[i - k] = ime->pend[i];
	ime->n = (uint8_t)(ime->n - k);
}

static bool is_vowel(char c) {
	return c == 'a' || c == 'i' || c == 'u' || c == 'e' || c == 'o';
}

bool z_kbd_ime_takes(uint32_t cp) {
	if ((cp >= 'a' && cp <= 'z') || (cp >= 'A' && cp <= 'Z')) return true;
	// The apostrophe too: after n it is the syllabic n (n'), and
	// z_kbd_ime_feed() passes it through as itself anywhere else. It
	// has to reach the converter to find out which.
	if (cp == '\'') return true;
	char s[2] = { (char)cp, 0 };
	return cp < 0x80 && romaji_exact(s) != NULL;
}

int z_kbd_ime_flush(z_kbd_ime_t *ime, uint32_t *out) {

	int k = 0;
	if ((ime->n == 1 && ime->pend[0] == 'n') ||
	    (ime->n == 2 && ime->pend[0] == 'n' && ime->pend[1] == 'n')) {
		out[k++] = kana_out(ime, 0x3093);				// ん
	} else {
		for (int i = 0; i < ime->n; i++) out[k++] = (uint8_t)ime->pend[i];
	}
	ime->n = 0;
	ime->pend[0] = 0;
	return k;

}

int z_kbd_ime_feed(z_kbd_ime_t *ime, uint32_t cp, uint32_t *out) {

	int k = 0;

	if (cp >= 'A' && cp <= 'Z') cp += 32;		// case does not change a kana

	// Punctuation stands alone: whatever is pending finishes first.
	if (!(cp >= 'a' && cp <= 'z') && cp != '\'') {
		k = z_kbd_ime_flush(ime, out);
		char s[2] = { (char)cp, 0 };
		const z_kbd_romaji_t *e = romaji_exact(s);
		if (e) k += emit_entry(ime, e, out + k);
		return k;
	}

	// n' is the syllabic n; an apostrophe anywhere else is itself.
	if (cp == '\'' && !(ime->n == 1 && ime->pend[0] == 'n')) {
		k = z_kbd_ime_flush(ime, out);
		out[k++] = '\'';
		return k;
	}

	if (ime->n >= Z_KBD_IME_PEND) k += z_kbd_ime_flush(ime, out);
	ime->pend[ime->n++] = (char)cp;
	ime->pend[ime->n] = 0;

	for (;;) {

		if (!ime->n) return k;

		// nn: the syllabic n -- but the second n may begin the next
		// syllable, as in konna (こんな), which is how the common
		// Japanese input methods read it. So nn waits for one more
		// letter: a vowel or y takes the second n with it.
		if (ime->n >= 2 && ime->pend[0] == 'n' && ime->pend[1] == 'n') {
			if (ime->n == 2) return k;
			out[k++] = kana_out(ime, 0x3093);			// ん
			char c2 = ime->pend[2];
			pend_drop(ime, (is_vowel(c2) || c2 == 'y') ? 1 : 2);
			continue;
		}

		const z_kbd_romaji_t *e = romaji_exact(ime->pend);
		bool longer = romaji_prefix(ime->pend, ime->n);

		if (e && !longer) {
			k += emit_entry(ime, e, out + k);
			ime->n = 0;
			ime->pend[0] = 0;
			return k;
		}
		if (longer) return k;					// could still become one

		char c0 = ime->pend[0], c1 = ime->n > 1 ? ime->pend[1] : 0;

		// kk, tt, ss ...: the small tsu, and the second letter goes on.
		if (c1 == c0 && !is_vowel(c0) && c0 != 'n') {
			out[k++] = kana_out(ime, 0x3063);			// っ
			pend_drop(ime, 1);
			continue;
		}

		// n before anything that cannot follow it in a syllable.
		if (c0 == 'n' && c1 && !is_vowel(c1) && c1 != 'y') {
			out[k++] = kana_out(ime, 0x3093);			// ん
			pend_drop(ime, 1);
			continue;
		}

		// Nothing will come of the first letter: it is itself.
		out[k++] = (uint8_t)c0;
		pend_drop(ime, 1);

	}

}

bool z_kbd_ime_backspace(z_kbd_ime_t *ime) {
	if (!ime->n) return false;
	ime->pend[--ime->n] = 0;
	return true;
}

